#!/usr/bin/env python3
# luxarch:worktree-sessions hook v3 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Whether a claude session holds a worktree: the process table, a lock's holder, the
`EnterWorktree` records, and the transcript a gone session left.

A session is live when a `claude` process works in the worktree (its own directory, or a process it
started there), when a running claude entered it with `EnterWorktree`, or when its lock names a
running holder (pid and start time, so a pid reused after a reboot is not it).

The process table is `/proc` where the host has one (Linux). Elsewhere (macOS) it is `ps` (each
process's name, parent and start time) and `lsof` (each process's directory), each trusted only
when its listing includes this process itself. A claude's own directory stays where it was
launched, the main checkout, whichever worktree it entered, so on every host the `EnterWorktree`
record is what shows an idle session owns a worktree. With neither table readable every session is
unknown, and unknown is live.

Python 3.9 and the standard library only, like the hook that loads it.
"""

from __future__ import annotations

import calendar
import contextlib
import functools
import json
import os
import re
import subprocess
import time
from pathlib import Path

from _worktree_git import out
from _worktree_submodules import init_submodules

PROC = Path("/proc")
# the portable process table, where there is no /proc: names, not paths, so PATH finds them
PS = "ps"
LSOF = "lsof"
SYSCTL = "sysctl"
# caught as a tuple named once: the canonical formatter writes an inline tuple without parentheses,
# which Python before 3.14 cannot parse, and these hooks run on a Mac's Python 3.9
_TOOL_ERRORS = (OSError, subprocess.SubprocessError)
_TIME_ERRORS = (ValueError, OverflowError)


HOLDER = re.compile(r"\(pid (\d+) start (\d+)\)")
ADOPTED = "claude session adopted "  # the lock `adopt` writes, its start time from this host's table


def _has_proc() -> bool:
    return (PROC / "self" / "stat").is_file()


def _tool(
    name: str, *args: str, env: dict[str, str], ok: tuple[int, ...] = (0,)
) -> str | None:
    """A process-table tool's output, or None when it cannot run or exits outside `ok`. A bare name
    not on PATH is tried in /usr/sbin, where macOS keeps lsof and sysctl."""
    for exe in (name,) if "/" in name else (name, f"/usr/sbin/{name}"):
        try:
            r = subprocess.run(
                [exe, *args],
                capture_output=True,
                text=True,
                errors="replace",
                timeout=20,
                check=False,
                env={**os.environ, **env},
            )
        except FileNotFoundError:
            continue
        except _TOOL_ERRORS:
            return None
        _LAST_EXIT[name] = r.returncode
        return r.stdout if r.returncode in ok else None
    return None


_LAST_EXIT: dict[str, int] = {}


def _ps_table() -> dict[str, tuple[str, str, str]]:
    """`ps`'s view: pid -> (command name, parent pid, start time in seconds since the epoch). Read in
    the C locale and in UTC, so every session's hook reads one start time as one number."""
    text = _tool(
        PS, "-A", "-o", "pid=,ppid=,lstart=,comm=", env={"LC_ALL": "C", "TZ": "UTC0"}
    )
    table: dict[str, tuple[str, str, str]] = {}
    for line in (text or "").splitlines():
        words = line.split(None, 7)
        if len(words) < 8 or not (words[0].isdigit() and words[1].isdigit()):
            continue
        try:
            start = calendar.timegm(
                time.strptime(" ".join(words[2:7]), "%a %b %d %H:%M:%S %Y")
            )
        except _TIME_ERRORS:
            continue
        table[words[0]] = (os.path.basename(words[7].strip()), words[1], str(start))
    return table


def _unescape(name: str) -> str | None:
    """A path as lsof printed it, with its `\\\\` turned back into one backslash; None when it holds
    any other escape (`\\xNN` for a byte its locale cannot print, `\\n`, ...), which no real path
    compares with."""
    out: list[str] = []
    i = 0
    while i < len(name):
        if name[i] != "\\":
            out.append(name[i])
            i += 1
        elif name[i + 1 : i + 2] == "\\":
            out.append("\\")
            i += 2
        else:
            return None
    return "".join(out)


def _lsof_cwds() -> tuple[dict[str, Path], bool, bool]:
    """`lsof`'s view: (pid -> the process's directory, exited non-zero, escaped), in the user's own
    locale. Exit 1 is lsof's answer when some process could not be read: the listing is taken, and
    `_snapshot` marks it partial. A path holding an escape lsof cannot be read back from marks the
    listing escaped."""
    text = _tool(LSOF, "-n", "-P", "-w", "-d", "cwd", "-Fpn", env={}, ok=(0, 1))
    failed = _LAST_EXIT.get(LSOF) != 0
    cwds: dict[str, Path] = {}
    escaped = False
    pid = ""
    for line in (text or "").splitlines():
        if line[:1] == "p":
            pid = line[1:]
        elif line[:1] == "n" and pid.isdigit() and line[1:].startswith("/"):
            name = _unescape(line[1:])
            if name is None:
                escaped = True
            else:
                cwds[pid] = Path(name)
    return cwds, failed, escaped


# (ps's table, lsof's directories, whether lsof left some process out)
Snapshot = tuple[dict[str, tuple[str, str, str]], dict[str, Path], bool]


@functools.lru_cache(maxsize=1)
def _snapshot() -> Snapshot | None:
    """`ps` and `lsof` read once per run of the hook, so every check judges the same moment, or None
    when they cannot be trusted. lsof runs first: a process it lists that is still running is then
    in `ps`'s table. Trusted only when the listings show this process as it is: lsof gives its
    directory exactly (so paths compare as written), and ps leads from it to the claude it runs
    under (so a claude can be recognised by name), and no path in the listing is escaped. Anything
    less, and every session is unknown.

    A process lsof lists that ps (run after it) does not has exited, lsof itself among them: it is
    dropped. A process ps lists that started before lsof ran but that lsof left out (another
    user's, which lsof skips without saying so) makes the listing partial, as lsof's exit 1 does:
    `complete_table` is then false, so nothing is pruned. Start times are whole seconds, so a
    process started in lsof's own second is not counted."""
    began = int(time.time())
    cwds, partial, escaped = _lsof_cwds()
    if escaped:
        return None
    table = _ps_table()
    cwds = {p: c for p, c in cwds.items() if p in table}
    partial = partial or any(
        p not in cwds and int(row[2]) < began for p, row in table.items()
    )
    pid = str(os.getpid())
    try:
        here = Path.cwd().resolve()
    except OSError:
        return None
    if cwds.get(pid) != here:
        return None
    for _ in range(64):
        row = table.get(pid)
        if row is None:
            return None
        if row[0] == "claude":
            return table, cwds, partial
        if row[1] in ("0", "1"):
            return None
        pid = row[1]
    return None


def _stat(pid: str) -> tuple[str, str, str] | None:
    """(command name, parent pid, start time) of a running process: clock ticks since boot from
    `/proc`, else seconds since the epoch from `ps`. One host always uses the same one."""
    if not _has_proc():
        snap = _snapshot()
        return snap[0].get(pid) if snap else None
    try:
        data = (PROC / pid / "stat").read_text(encoding="utf-8", errors="replace")
    except OSError:
        return None
    close = data.rfind(")")
    rest = data[close + 2 :].split()
    if close < 0 or len(rest) < 20:
        return None
    return data[data.find("(") + 1 : close], rest[1], rest[19]


def _claude_of(pid: str) -> str:
    """The `claude` process `pid` is, or runs under (its shells and their children), else ""."""
    for _ in range(64):
        st = _stat(pid)
        if st is None:
            return ""
        if st[0] == "claude":
            return pid
        if st[1] in ("0", "1"):
            return ""
        pid = st[1]
    return ""


def me() -> tuple[str, str] | None:
    """(pid, start) of the claude session running this script."""
    pid = _claude_of(str(os.getpid()))
    st = _stat(pid) if pid else None
    return (pid, st[2]) if st else None


def working_in(path: Path) -> list[str]:
    """The pid of every process whose directory is `path` or inside it, claude or not (the owner's
    shell, a dev server, a job an agent left running)."""
    if not _has_proc():
        snap = _snapshot()
        try:
            real = (
                path.resolve()
            )  # lsof gives real paths: /tmp is /private/tmp on macOS
        except _PATH_ERRORS:
            real = path
        cwds = snap[1].items() if snap else ()
        return [
            pid
            for pid, cwd in cwds
            if cwd in (path, real) or {path, real} & set(cwd.parents)
        ]
    try:
        procs = [p for p in PROC.iterdir() if p.name.isdigit()]
    except OSError:
        return []
    found: list[str] = []
    for p in procs:
        try:
            cwd = Path(os.readlink(p / "cwd"))
        except OSError:
            continue
        if cwd == path or path in cwd.parents:
            found.append(p.name)
    return found


def sessions_in(path: Path) -> set[str]:
    """Every claude working in `path`: its own directory is there, or a process it started is (a
    session in the main checkout that `cd`s into a worktree is working in it)."""
    return {h for h in (_claude_of(pid) for pid in working_in(path)) if h}


def unattributed_in(path: Path) -> list[str]:
    """Without `/proc`: every process working in `path` that `ps` leads to no claude. On a Mac that
    may be a claude whose process is not named `claude`, so the caller reads it as live, never as
    nobody. (With `/proc`, a claude is always named `claude`.)"""
    if _has_proc():
        return []
    return [pid for pid in working_in(path) if not _claude_of(pid)]


def complete_table() -> bool:
    """Whether the process table lists every process: `/proc` does; an lsof that exited 1 left some
    process out (another user's, say), so a worktree it shows nobody in may still have one."""
    if _has_proc():
        return True
    snap = _snapshot()
    return snap is not None and not snap[2]


def lock_holder(reason: str) -> tuple[str, bool]:
    """(pid, running) of the holder a lock reason names (Claude Code writes `claude session <name>
    (pid N start T)`, T in `/proc`'s clock ticks). A lock that names no holder reads as running:
    nothing shows it is gone. Without `/proc`, Claude Code's T cannot be compared with `ps`'s start
    time, so a running claude with that pid is taken as its holder; a lock `adopt` wrote carries
    this host's own start time, and is compared."""
    m = HOLDER.search(reason)
    if not m:
        return "", True
    st = _stat(m.group(1))
    compare = _has_proc() or reason.startswith(ADOPTED)
    same_start = not compare or bool(st and st[2] == m.group(2))
    return m.group(1), bool(st and st[0] == "claude" and same_start)


ENTERED = "luxarch-entered"
# The sessions that made the worktree with `worktree.py add` for a subagent: theirs until it lands.
ADDED = "luxarch-added"


# A path from the event that cannot be resolved: missing, unreadable, or holding a NUL (ValueError).
_PATH_ERRORS = (OSError, ValueError)


def entered_by(path: Path, folder: str = ENTERED) -> set[str]:
    """Every running claude that entered the worktree at `path` (`EnterWorktree`, recorded by
    `record_entry`, or `add`). A session that stepped into another worktree with `EnterWorktree
    path=` left no process inside this one and Claude Code kept no lock on it, yet the session still
    owns it. With `folder=ADDED`, the sessions that made it with `add`."""
    gitdir = out(path, "rev-parse", "--absolute-git-dir")
    if not gitdir:
        return set()
    try:
        names = [p.name for p in (Path(gitdir) / folder).iterdir()]
    except OSError:
        return set()
    return {name.partition("-")[0] for name in names if _entry_live(name)}


def _entry_live(name: str) -> bool:
    """A `<pid>-<start>` record names a running claude: that pid, with that start time."""
    pid, _, start = name.partition("-")
    st = _stat(pid) if pid.isdigit() else None
    return bool(st and st[0] == "claude" and st[2] == start)


def record_entry(main: Path, event: str) -> None:
    """After `EnterWorktree`, record the calling session in the entered worktree's git dir: one file
    per session (`<pid>-<start>`), so two sessions never write the same file, and the records of
    sessions that are gone are cleared. The worktree is the event's `path`, else its `name` under
    `.claude/worktrees/`, else the event's `cwd`; only an agent worktree is recorded. Then each
    submodule the main checkout has populated is initialised there (`init_submodules`)."""
    target = entered_worktree(main, event)
    if target is None:
        return
    record_session(target)
    init_submodules(main, target)


def record_session(target: Path, folders: tuple[str, ...] = (ENTERED,)) -> bool:
    """Record the calling claude session in the worktree at `target`, as `EnterWorktree` does
    (`<git dir>/luxarch-entered/<pid>-<start>`; `add` also writes it under `luxarch-added/`),
    clearing the records of sessions that are gone. Whether it was recorded: False when no claude
    runs this, or a record cannot be written."""
    mine = me()
    gitdir = out(target, "rev-parse", "--absolute-git-dir")
    if mine is None or not gitdir:
        return False
    try:
        for name in folders:
            folder = Path(gitdir) / name
            folder.mkdir(exist_ok=True)
            for old in folder.iterdir():
                if not _entry_live(old.name):
                    with contextlib.suppress(OSError):
                        old.unlink()
            (folder / f"{mine[0]}-{mine[1]}").touch()
    except OSError:
        return False
    return True


# Claude Code's own name for a subagent's isolation worktree (`Agent isolation: "worktree"`) and the
# lock it writes there, naming the parent session's pid.
HARNESS_AGENT = re.compile(r"^agent-[0-9a-f]{6,64}$")
HARNESS_LOCK = "claude agent "
# A subagent record that cannot be read, or is not JSON.
_META_ERRORS = (OSError, ValueError)


def clear_session(target: Path) -> None:
    """Remove the calling session's `add` record from the worktree at `target`: its agent landed
    there and is done, so the record no longer holds it for that session's own prune."""
    mine = me()
    gitdir = out(target, "rev-parse", "--absolute-git-dir")
    if mine is None or not gitdir:
        return
    with contextlib.suppress(OSError):
        (Path(gitdir) / ADDED / f"{mine[0]}-{mine[1]}").unlink()


def _subagent_records(home: str) -> tuple[tuple[str, object], ...] | None:
    """Every subagent record Claude Code keeps under `home`, any project and session: (file name,
    its JSON), read afresh for each worktree judged (a child agent may start in one meanwhile). None when any of them cannot be read: a record being written may
    be the one that says an agent still runs."""
    out_: list[tuple[str, object]] = []
    try:
        metas = list(Path(home).glob("projects/*/*/subagents/*.meta.json"))
    except OSError:
        return None
    for meta in metas:
        try:
            out_.append((meta.name, json.loads(meta.read_text(encoding="utf-8"))))
        except _META_ERRORS:
            return None
    return tuple(out_)


def _names_worktree(data: dict[str, object], path: Path) -> bool:
    """A subagent record that runs in the worktree at `path`: its `cwd` or `inheritedWorktreePath`
    is the worktree or a directory inside it."""
    for key in ("cwd", "inheritedWorktreePath"):
        value = data.get(key)
        if not isinstance(value, str) or not value:
            continue
        try:
            where = Path(value).resolve()
        except _PATH_ERRORS:
            return True  # unreadable: taken as naming it
        if where == path or path in where.parents:
            return True
    return False


def harness_agent_finished(path: Path) -> bool:
    """Claude Code recorded the subagent whose isolation worktree is `path` as finished, and nothing
    else runs in it: every record of that agent, in any project (a revived agent is recorded
    again), says `"finished": true`, and no record of an unfinished subagent names the worktree as
    its `cwd` or `inheritedWorktreePath` (a child agent runs in its parent's worktree). No record, or
    any record that cannot be read, is not finished: the agent may run."""
    name = path.name
    if not HARNESS_AGENT.match(name):
        return False
    home = os.environ.get("CLAUDE_CONFIG_DIR") or str(Path.home() / ".claude")
    records = _subagent_records(home)
    if records is None:
        return False
    try:
        here = path.resolve()
    except _PATH_ERRORS:
        return False
    own = False
    for file_name, data in records:
        if not isinstance(data, dict):
            return False
        done = data.get("finished") is True
        if file_name == f"{name}.meta.json":
            if not done:
                return False
            own = True
        elif not done and _names_worktree(data, here):
            return False
    return own


def entered_worktree(main: Path, event: str) -> Path | None:
    """The agent worktree an `EnterWorktree` event entered, resolved, or None."""
    try:
        data = json.loads(event)
    except ValueError:
        return None
    if not isinstance(data, dict) or data.get("tool_name") != "EnterWorktree":
        return None
    given = data.get("tool_input")
    given = given if isinstance(given, dict) else {}
    answer = data.get("tool_response")
    answer = answer if isinstance(answer, dict) else {}
    agents = main / ".claude" / "worktrees"
    target = None
    if isinstance(answer.get("worktreePath"), str) and answer["worktreePath"]:
        # Claude Code's own resolution: `path` is relative to the session's cwd before the switch,
        # which this hook cannot know (a switch from one worktree is `path=../<KEY>`)
        target = Path(answer["worktreePath"])
    elif isinstance(given.get("path"), str) and Path(given["path"]).is_absolute():
        target = Path(given["path"])
    elif isinstance(given.get("name"), str) and given["name"]:
        target = agents / given["name"]
    elif isinstance(data.get("cwd"), str) and data["cwd"]:
        target = Path(data["cwd"])  # where the session is once the switch is done
    if target is None:
        return None
    try:
        target = target.resolve()
    except _PATH_ERRORS:
        return None
    if target.parent != agents.resolve() or not target.is_dir():
        return None
    return target


def last_session(path: Path) -> Path | None:
    """The newest transcript Claude Code filed for `path`: `<config>/projects/<path, every character
    but [A-Za-z0-9-] as ->/<session id>.jsonl`."""
    home = Path(os.environ.get("CLAUDE_CONFIG_DIR") or Path.home() / ".claude")
    folder = home / "projects" / re.sub(r"[^A-Za-z0-9-]", "-", str(path))
    try:
        files = sorted(folder.glob("*.jsonl"), key=lambda f: f.stat().st_mtime)
    except OSError:
        return None
    return files[-1] if files else None


def scratchpad(session: str) -> Path | None:
    """The session's scratchpad: `/tmp/claude-<uid>/<launch folder>/<session id>/scratchpad`."""
    for d in sorted(Path("/tmp").glob(f"claude-*/*/{session}/scratchpad")):
        return d
    return None


def boot_time() -> float:
    if not _has_proc():
        # macOS: `{ sec = 1730000000, usec = 0 } Mon Nov  2 ...`
        m = re.search(
            r"\bsec = (\d+)", _tool(SYSCTL, "-n", "kern.boottime", env={}) or ""
        )
        return float(m.group(1)) if m else 0.0
    try:
        text = (PROC / "stat").read_text(encoding="utf-8")
    except OSError:
        return 0.0
    for line in text.splitlines():
        words = line.split()
        if words[:1] == ["btime"] and len(words) > 1 and words[1].isdigit():
            return float(words[1])
    return 0.0


def process_table() -> bool:
    """Whether this host's process table can be read the way the session checks read it.

    Every liveness fact here is a process's name, parent, start time and directory: from `/proc`,
    else from `ps` and `lsof` when they show this process as it is (`_snapshot`). Where neither can
    be read, each check finds nothing, and nothing found would read as "every session is gone": live
    worktrees offered as ADOPT, and a worktree a live session sits in pruned. So without one,
    liveness is unknown, and unknown is live. Run by hand outside a claude session, a Mac reads
    every session as unknown: the hook is run from the session."""
    return _has_proc() or _snapshot() is not None


UNKNOWN_SESSION = (
    "session unknown: this host has no /proc, and ps and lsof could not show which claude runs "
    "where, so whether a claude works here cannot be read (not offered to adopt, never pruned); "
    "check by hand"
)


def session_state(path: Path, lock: str | None, caller: str) -> tuple[bool, bool, str]:
    """(live, the caller's own, what to print) for the session of the worktree at `path`. The
    caller's own session is not another agent: it never makes a worktree live for the caller's
    `--prune` or `adopt`. With no readable process table every session is unknown, so live."""
    if not process_table():
        return True, False, UNKNOWN_SESSION
    working = sessions_in(path)
    unattributed = unattributed_in(path)
    if unattributed:
        pids = ", ".join(sorted(unattributed))
        return (
            True,
            False,
            f"LIVE (pid {pids} works here, tied to no claude: taken as live)",
        )
    others = sorted(working - {caller})
    if others:
        return True, False, f"LIVE (claude pid {', '.join(others)} works here)"
    entered = entered_by(path)
    away = sorted(entered - {caller})
    if away:
        return True, False, f"entered by a live session (claude pid {', '.join(away)})"
    pid, running = lock_holder(lock) if lock is not None else ("", False)
    if lock is not None and not pid:
        return True, False, "locked (the lock names no holder: taken as live)"
    # the lock is the caller's only with its start time too: a reused pid is not the holder
    if caller and (caller in working or (pid == caller and running)):
        return False, True, f"this session's (pid {caller})"
    if running:
        return True, False, f"locked by a live session (pid {pid})"
    # after the lock: the caller's record never outranks another live session's lock
    if caller and caller in entered:
        return False, True, f"this session's (pid {caller})"
    t = last_session(path)
    stale = " (stale lock: its holder is gone)" if lock is not None else ""
    if t is None:
        return False, False, f"no live session, none filed here{stale}"
    mtime = t.stat().st_mtime
    when = time.strftime("%m-%d %H:%M", time.localtime(mtime))
    why = "before the last boot" if mtime < boot_time() else "exited"
    return False, False, f"session {t.stem} gone ({why}, last write {when}){stale}"
